def build(p):
    import cadquery as cq
    out = None
    for a in (0, 90, 180, 270):
        ra = math.radians(a)
        x, z = (p['R_station'] - p['e_head']) * math.cos(ra), -(p['R_station'] - p['e_head']) * math.sin(ra)
        ro = p['ring_id'] / 2 + p['ring_w'] + 20
        body = cq.Workplane("XZ").circle(ro).circle(p['ring_id'] / 2 + p['ring_w'] + 1).extrude(-p['h']).translate((0, p['y0'] + p['h'], 0))
        cap = cq.Workplane("XZ").circle(ro).extrude(-25).translate((0, p['y0'] + p['h'] + 25, 0))
        sh = cq.Workplane("XZ").circle(p['shaft_d'] / 2).extrude(-(p['y_top'] - p['y0'] - p['h'] - 25)).translate((0, p['y_top'], 0))
        h = body.union(cap).union(sh).translate((x, 0, z))
        out = h if out is None else out.union(h)
    return out
